    def spans(seps, N):
        sp=[]; s=0
        for x in seps+[N]:
            if x>s: sp.append((s,x-1))
            s=x+1 if x<N else x
        return sp
    rspans = spans(srows,Hh); cspans = spans(scols,Ww)
    rp={}
