def regions_of(inp, sep, bg):
    Hh,Ww=len(inp),len(inp[0])
    srows=[r for r in range(Hh) if all(inp[r][c]==sep for c in range(Ww))]
    scols=[c for c in range(Ww) if all(inp[r][c]==sep for r in range(Hh))]
    def spans(seps,N):
        sp=[];s=0
        for x in list(seps)+[N]:
            if x>s: sp.append((s,x-1))
            s=x+1
        return sp
    rs,cs=spans(srows,Hh),spans(scols,Ww)
    out=[]
    for i,(r0,r1) in enumerate(rs):
        for j,(c0,c1) in enumerate(cs):
            pos=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if inp[r][c]!=sep and inp[r][c]!=bg]
            out.append(dict(i=i,j=j,r0=r0,c0=c0,r1=r1,c1=c1,pos=pos))
    return out

