def cross_line_flags(rg, inp, sep, bg, Hh, Ww):
    # for each anomaly, does there exist a straight line (row,col,diag,anti-diag) containing
    # this anomaly AND another anomaly in a DIFFERENT region?
    pos = rg['pos']
    dirs = [(0,1),(1,0),(1,1),(1,-1)]
    flags = []
    for (r,c) in pos:
        ok = False
        for dr,dc in dirs:
            pts = [(rr,cc) for rr in range(Hh) for cc in range(Ww)
                   if inp[rr][cc]!=sep and inp[rr][cc]!=bg and (rr-r)*dc==(cc-c)*dr]
            # other anomalies on same line in different region
            for (rr,cc) in pts:
                if (rr,cc)!=(r,c) and not (rg['r0']<=rr<=rg['r1'] and rg['c0']<=cc<=rg['c1']):
